import fitz
import os
import re

def redact_with_pymupdf(input_path: str, output_path: str, patterns: list[str], regex_patterns: list[str]):
    """Redact specific patterns from PDF using PyMuPDF."""
    doc = fitz.open(input_path)

    # Find References page - stop redacting there
    references_page = None
    for i, page in enumerate(doc):
        text = page.get_text().lower()
        if "references" in text:
            references_page = i
            break

    for page_num, page in enumerate(doc):
        # Handle References section
        ref_rect = None
        if references_page is not None and page_num == references_page:
            ref_instances = page.search_for("references")
            if ref_instances:
                ref_rect = ref_instances[0]

        if references_page is not None and page_num > references_page:
            break

        # Redact literal patterns
        for pattern in patterns:
            for rect in page.search_for(pattern):
                if ref_rect is None or rect.y1 <= ref_rect.y0:
                    page.add_redact_annot(rect, fill=(0, 0, 0))

        # Redact regex patterns
        text_page = page.get_text("words") # Get words with coordinates
        # word: (x0, y0, x1, y1, "word", block_no, line_no, word_no)
        for rp in regex_patterns:
            full_text = page.get_text()
            for match in re.finditer(rp, full_text):
                matched_text = match.group()
                for rect in page.search_for(matched_text):
                    if ref_rect is None or rect.y1 <= ref_rect.y0:
                        page.add_redact_annot(rect, fill=(0, 0, 0))

        page.apply_redactions()

    os.makedirs(os.path.dirname(output_path), exist_ok=True)
    doc.save(output_path)
    doc.close()

